def main(a, b, c):
    if a <= 0 or b <= 0 or c <= 0:
        return 0
    sides = sorted([a, b, c])
    if sides[0] + sides[1] <= sides[2]:
        return 0
    if a == b == c:
        return 1
    elif a == b or b == c or a == c:
        return 2
    else:
        return 3

isqrt:
def main(n):
    r = int(n ** 0.5)
    while r * r > n:
        r -= 1
    while (r + 1) * (r + 1) <= n:
        r += 1
    return r

is-prime:
def main(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

lcm:
def main(a, b):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x
    return (a * b) // gcd(a, b)

